export class AgentProtocolError extends Error {
  readonly code = 'AGENT_PROTOCOL_ERROR';

  constructor(readonly issues: string[]) {
    super(`Agent 协议校验失败: ${issues.join('; ')}`);
    this.name = AgentProtocolError.name;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function matchesType(type: string, value: unknown): boolean {
  if (type === 'null') return value === null;
  if (type === 'object') return isRecord(value);
  if (type === 'array') return Array.isArray(value);
  if (type === 'string') return typeof value === 'string';
  if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (type === 'integer') return typeof value === 'number' && Number.isSafeInteger(value);
  if (type === 'boolean') return typeof value === 'boolean';
  return false;
}

function validateNode(schema: JsonSchema, value: unknown, path: string, issues: string[]): void {
  if (Array.isArray(schema.oneOf)) {
    const matches = schema.oneOf.filter((candidate) => {
      const candidateIssues: string[] = [];
      validateNode(candidate as JsonSchema, value, path, candidateIssues);
      return candidateIssues.length === 0;
    });
    if (matches.length !== 1) issues.push(`${path} 必须且只能匹配一个 schema`);
    return;
  }
  if (Object.prototype.hasOwnProperty.call(schema, 'const') && value !== schema.const) {
    issues.push(`${path} const 不匹配`);
    return;
  }
  if (Array.isArray(schema.enum) && !schema.enum.includes(value)) {
    issues.push(`${path} 枚举不合法`);
    return;
  }
  if (schema.type) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    if (!types.some((type) => matchesType(String(type), value))) {
      issues.push(`${path} 类型不合法`);
      return;
    }
  }
  if (typeof value === 'string') {
    if (typeof schema.minLength === 'number' && value.length < schema.minLength)
      issues.push(`${path} 太短`);
    if (typeof schema.maxLength === 'number' && value.length > schema.maxLength)
      issues.push(`${path} 太长`);
    if (typeof schema.pattern === 'string' && !new RegExp(schema.pattern).test(value))
      issues.push(`${path} 格式不匹配`);
    if (
      schema.format === 'date' &&
      (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(`${value}T00:00:00.000Z`)))
    )
      issues.push(`${path} 日期不合法`);
    if (schema.format === 'date-time' && Number.isNaN(Date.parse(value)))
      issues.push(`${path} 时间不合法`);
  }
  if (typeof value === 'number') {
    if (typeof schema.minimum === 'number' && value < schema.minimum)
      issues.push(`${path} 小于最小值`);
    if (typeof schema.maximum === 'number' && value > schema.maximum)
      issues.push(`${path} 超过最大值`);
  }
  if (Array.isArray(value)) {
    if (typeof schema.minItems === 'number' && value.length < schema.minItems)
      issues.push(`${path} 元素不足`);
    if (typeof schema.maxItems === 'number' && value.length > schema.maxItems)
      issues.push(`${path} 元素过多`);
    if (isRecord(schema.items))
      value.forEach((item, index) =>
        validateNode(schema.items as JsonSchema, item, `${path}[${index}]`, issues)
      );
  }
  if (isRecord(value)) {
    const properties = isRecord(schema.properties) ? schema.properties : {};
    const required = Array.isArray(schema.required) ? schema.required.map(String) : [];
    required.forEach((key) => {
      if (!Object.prototype.hasOwnProperty.call(value, key)) issues.push(`${path}.${key} 缺失`);
    });
    Object.entries(value).forEach(([key, propertyValue]) => {
      const propertySchema = properties[key];
      if (isRecord(propertySchema))
        validateNode(propertySchema, propertyValue, `${path}.${key}`, issues);
      else if (schema.additionalProperties === false) issues.push(`${path}.${key} 不允许出现`);
    });
  }
}

function assertSchema<T>(schema: JsonSchema, input: unknown, label: string): T {
  const issues: string[] = [];
  validateNode(schema, input, label, issues);
  if (issues.length > 0) throw new AgentProtocolError(issues);
  return input as T;
}

function schemaDefinition(name: 'AgentSseEvent' | 'MessageBlock'): JsonSchema {
  const definitions = AGENT_CONTRACT_JSON_SCHEMA.definitions as Record<string, JsonSchema>;
  return definitions[name];
}

export function parseAgentSseEvent(input: unknown): AgentSseEvent {
  return assertSchema<AgentSseEvent>(schemaDefinition('AgentSseEvent'), input, 'AgentSseEvent');
}

export function parseMessageBlock(input: unknown): MessageBlock {
  const block = assertSchema<MessageBlock>(schemaDefinition('MessageBlock'), input, 'MessageBlock');
  if (block.type === 'MARKDOWN' && /<\/?[A-Za-z][^>]*>/.test(block.text)) {
    throw new AgentProtocolError(['MessageBlock.text 禁止 raw HTML']);
  }
  return block;
}

export function isSupportedMessageBlock(input: unknown): input is MessageBlock {
  try {
    parseMessageBlock(input);
    return true;
  } catch {
    return false;
  }
}
